import React, { useEffect, useState } from "react";
import api from "../services/api";
import "./MLPredictionWidget.css"; 

const MLPredictionWidget = () => {
  const [failureRisk, setFailureRisk] = useState(null);
  const [reasons, setReasons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const fetchPrediction = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Unauthorized: Please log in.");
        setLoading(false);
        return;
      }

      const metricsResponse = await api.get("/api/auth/metrics/", {
        headers: { Authorization: `Token ${token}` },
      });

      if (metricsResponse.data.length === 0) {
        setError("No metrics data available for prediction.");
        setLoading(false);
        return;
      }

      const latestMetrics = metricsResponse.data[0];
      const webStatus = JSON.parse(latestMetrics.web_service_status || "{}");
      const dbStatus = JSON.parse(latestMetrics.db_service_status || "{}");

      let failureDetected = false;
      let riskReasons = [];

      if (Object.values(webStatus).includes("inactive")) {
        riskReasons.push("Web Service Down ❌");
        failureDetected = true;
      }

      if (Object.values(dbStatus).includes("inactive")) {
        riskReasons.push("Database Service Down ❌");
        failureDetected = true;
      }

      if (failureDetected) {
        setFailureRisk(true);
        setReasons(riskReasons);
      } else {
        setFailureRisk(false);
        setReasons(["No critical failures detected"]);
      }

      setLoading(false);
    } catch (err) {
      console.error("Prediction API Error:", err);
      setError("Failed to fetch AI predictions.");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPrediction();
    const interval = setInterval(fetchPrediction, 9500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="ml-prediction-widget">
      <h3>AI Failure Prediction</h3>
      {loading ? <p>Loading predictions...</p> : (
        <>
          <p><strong>Failure Risk:</strong> {failureRisk ? "⚠️ High Risk" : "✅ Low Risk"}</p>
          <ul>{reasons.map((reason, idx) => <li key={idx}>{reason}</li>)}</ul>
        </>
      )}
    </div>
  );
};

export default MLPredictionWidget;
